#[test]
fn crash_child() {
    let Ok(root) = std::env::var("TWODRIVE_JOURNAL_CHILD_ROOT") else {
        return;
    };
    let (db, cache, _) = paths(Path::new(&root));
    let j = CacheJournal::open(db, &cache, &hash(b"generated-provider-binding")).unwrap();
    if std::env::var("TWODRIVE_JOURNAL_CHILD_MODE").unwrap() == "write" {
        let mut writer = j.open_write(ID).unwrap();
        writer.set_len(0).unwrap();
        writer.write_all(EDITED).unwrap();
        writer.sync_all().unwrap();
        std::process::exit(0);
    }
    let _lease = j.begin_upload(ID, digest).unwrap();
    std::process::exit(0);
}
fn child(root: &Path, mode: &str) {
    let status = Command::new(std::env::current_exe().unwrap())
        .args(["--exact", "crash_child", "--nocapture"])
        .env("TWODRIVE_JOURNAL_CHILD_ROOT", root)
        .env("TWODRIVE_JOURNAL_CHILD_MODE", mode)
        .status()
        .unwrap();
    assert!(status.success());
}
